 transfer:[[102,2],[105,5],[104,3]],
 independent:[[38,2],[40,5],[32,3]],
 independent2:[[45,2],[35,5],[33,3]],
 delayed:[[31,2],[30,5],[25,3]],
 independent3:[[46,2],[47,5],[45,3]],
