'use strict';
function factorPairs(n){const pairs=[];for(let d=1;d*d<=n;d++)if(n%d===0)pairs.push([d,n/d]);return pairs}
function factorValues(n){return [...new Set(factorPairs(n).flat())].sort((a,b)=>a-b)}
function factorState(task){return draft.work??(draft.work={active:0,cards:task.numbers.map(()=>({width:1,laid:0,pairs:[],collected:[],count:0,choice:'',palette:false})),moves:0,log:[]})}
function factorShape(n,card){const cols=card.width,rows=Math.ceil(card.laid/cols);if(!rows)return `<div class="factor-unlaid">材料盘：${n}块，尚未铺入长方阵。</div>`;const cells=Array.from({length:rows*cols},(_,i)=>`<rect x="${(i%cols)*16+2}" y="${Math.floor(i/cols)*16+2}" width="14" height="14" rx="1" fill="${i<card.laid?'#efbd73':'#ffffff'}" stroke="${i<card.laid?'#986933':'#8ba799'}" ${i<card.laid?'':'stroke-dasharray="2 2"'}/>`).join('');return `<svg class="factor-shape" viewBox="0 0 ${cols*16+4} ${rows*16+4}" width="${cols*16+4}" height="${rows*16+4}" role="img" aria-label="铺${card.laid}块，每行${cols}格，共${rows}行，末行缺${rows*cols-card.laid}格">${cells}</svg>`}
