'use strict';
function cycleMod(n,m){return (n%m+m)%m}
function cycleOrigin(task){return task.kind==='weekday'?task.start:task.indexBase===0?0:-1}
function cycleDirection(task){return task.kind==='weekday'?(task.direction||1):1}
function cyclePosition(task,steps,n){return cycleMod(cycleOrigin(task)+cycleDirection(task)*steps,n)}
function cycleAnswer(task,n){const pos=cyclePosition(task,task.target,n);return task.kind==='weekday'||task.indexBase===0?pos:pos+1}
function cycleState(task){return draft.work??(draft.work={steps:0,cursor:cycleOrigin(task),walk:[],choice:null,digit:1,working:1,phase:0,generated:[],products:[],period:0,ringMade:false,zeroConfirmed:false,moves:0,log:[]})}
function cycleBase(task,w){return task.kind==='power'?(w.ringMade?w.generated.slice(0,w.period).map(String):[]):task.base}
function cycleGenerator(task,w){return `<section class="cycle-generator"><h4>逐轮乘${task.factor}，只保留个位</h4><p>机器内 ${w.working}；${['等待乘','已乘，等待去掉十棒','已保留个位，等待记下'][w.phase]}。</p><div class="cycle-place"><div><b>十棒 ${Math.floor(w.working/10)}</b>${Array.from({length:Math.floor(w.working/10)},()=>'<span>10</span>').join('')}</div><div><b>散点 ${w.working%10}</b>${Array.from({length:w.working%10},()=>'<i aria-hidden="true"></i>').join('')}</div></div><div class="work-buttons"><button data-action="cycleMultiply" ${w.phase!==0||w.generated.length>=task.period+1?'disabled':''}>×${task.factor}</button><button data-action="cycleUnits" ${w.phase!==1?'disabled':''}>去掉十棒，只留个位</button><button data-action="cycleCommit" ${w.phase!==2?'disabled':''}>记下这个末位</button></div><p>已生成末位：${w.generated.join('、')||'无'}。</p>${w.generated.length>=task.period+1?`<div class="work-buttons">${Array.from({length:w.generated.length-1},(_,i)=>i+1).map(n=>`<button data-action="cyclePeriod" data-value="${n}" aria-pressed="${w.period===n}">圈${n}项作周期</button>`).join('')}<button data-action="cycleMake" ${!w.period?'disabled':''}>把圈出的周期带入环</button></div>`:''}</section>`}
function cycleZeroBoard(task,w,undo){const dot='<i class="equation-return-dot" data-object-id="U0"></i>';return `<div class="board cycle-board"><h3>${esc(task.context)}</h3><div class="equation-pans"><section><b>原单位1</b>${w.zeroConfirmed?'已移到结果盘':dot}</section><section><b>0次乘法的结果盘</b>${w.zeroConfirmed?dot:'尚未移入'}</section></div><p>一次也不乘；移动原单位只用来记录结果。</p><div class="work-buttons"><button data-action="cycleZeroConfirm" ${w.zeroConfirmed?'disabled':''}>把原单位移到结果盘</button>${undo}</div>${choiceButtons(task,[['1','个位是1'],['0','个位是0'],['4','个位是4']],'cycleZeroChoice','zero-exponent',w.choice===null?'':String(w.choice))}</div>`}
function cycleBoard(task){const w=cycleState(task),base=cycleBase(task,w),n=base.length,undo=`<button data-action="cycleUndo" ${w.log.length?'':'disabled'}>↩ 撤回</button>`;if(task.kind==='power'&&task.target===0)return cycleZeroBoard(task,w,undo);
 if(task.kind==='power'&&!w.ringMade)return `<div class="board cycle-board"><h3>${esc(task.context)}</h3><div class="work-buttons">${undo}</div>${cycleGenerator(task,w)}</div>`;
 const positions=base.map((label,i)=>{const theta=2*Math.PI*i/n-Math.PI/2,x=140+97*Math.cos(theta),y=140+97*Math.sin(theta);return `<g><circle cx="${x}" cy="${y}" r="${n===7?27:30}" fill="${w.cursor===i?'#ffd18b':'#e4f3e8'}" stroke="${w.cursor===i?'#a76b2c':'#679b7c'}" stroke-width="${w.cursor===i?4:2}"/><text x="${x}" y="${y-4}" text-anchor="middle" font-size="${n===7?13:15}" fill="#234e45">${esc(label)}</text><text x="${x}" y="${y+15}" text-anchor="middle" font-size="12">${task.kind==='weekday'?'':task.indexBase===0?'编号'+i:i+1+'位'}</text></g>`}).join('');
 const rounds=Math.floor(w.steps/n),rest=w.steps%n,groups=Array.from({length:Math.ceil(w.walk.length/n)},(_,i)=>w.walk.slice(i*n,(i+1)*n));return `<div class="board cycle-board"><h3>${esc(task.context)}</h3>${task.kind==='power'?`<p>生成末位 ${w.generated.join('、')}；采用周期${n}。</p>`:''}<p>${task.kind==='weekday'?'起点今天是'+esc(task.base[task.start])+(task.direction===-1?'，已倒数':'，已过'):task.indexBase===0?'从编号0开始，已前进':'从还没数第1项开始，已数'} ${w.steps} ${task.kind==='weekday'?'天':task.indexBase===0?'步':'项'}：${rounds}整轮＋${rest}${task.kind==='weekday'?'天':task.indexBase===0?'步':'项'}。</p><svg class="cycle-ring" viewBox="0 0 280 280" role="img" aria-label="周期${n}，当前${w.cursor<0?'还没数第1项':base[w.cursor]+(task.indexBase===0?'，轮内编号'+w.cursor:'，周期第'+(w.cursor+1)+'位')}"><circle cx="140" cy="140" r="97" fill="none" stroke="#9bc2ac" stroke-width="3"/>${positions}<text x="140" y="138" text-anchor="middle" font-size="16">${w.steps}/${task.target}</text><text x="140" y="160" text-anchor="middle" font-size="13">${task.kind==='weekday'?task.direction===-1?'已经倒数的天数':'已经过的天数':task.indexBase===0?'已前进的步数':'已经数的项数'}</text></svg><div class="work-buttons"><button data-action="cycleAdvance" ${w.steps>=task.target?'disabled':''}>${task.kind==='weekday'?task.direction===-1?'倒数1天':'过1天':task.indexBase===0?'走到下一编号':'数下一项'}</button><button data-action="cycleRound" ${w.steps+n>task.target?'disabled':''}>实际${task.direction===-1?'倒走':'走完'}一整轮${n}${task.kind==='weekday'?'天':task.indexBase===0?'步':'项'}</button>${undo}</div><div class="cycle-walk">${groups.map((g,i)=>`<section><b>${g.length===n?'完整':'剩余'}第${i+1}段</b><div>${g.map((index,j)=>`<span>${task.kind==='weekday'?(task.direction===-1?'倒数':'过')+(i*n+j+1)+'天':task.indexBase===0?'编号'+(i*n+j+1):'第'+(i*n+j+1)+'项'} ${esc(base[index])}</span>`).join('')}</div></section>`).join('')}</div><div class="work-buttons">${task.kind==='weekday'?base.map((name,i)=>`<button data-action="cycleChoice" data-value="${i}" aria-pressed="${w.choice===i}">${esc(name)}</button>`).join(''):Array.from({length:n+(task.indexBase===0?0:1)},(_,i)=>`<button data-action="cycleChoice" data-value="${i}" aria-pressed="${w.choice===i}">${task.indexBase===0?'编号'+i+' · '+esc(base[i]):'第'+i+'位'+(i?' · '+esc(base[i-1]):'')}</button>`).join('')}</div></div>`;
}
function cycleGrade(task){const w=cycleState(task);if(task.kind==='power'&&task.target===0)return {ok:w.zeroConfirmed&&w.choice===1&&w.generated.length===0&&w.products.length===0,incomplete:w.moves===0,reason:'非零底数从单位1开始，零次乘法保留起始单位1。'};const base=cycleBase(task,w),n=base.length;if(!n)return {ok:false,incomplete:w.moves===0,reason:'先实际生成末位序列，圈出最短周期并带入环。'};const expected=cyclePosition(task,task.target,n);let ok=w.steps===task.target&&w.walk.length===task.target&&w.cursor===expected&&w.choice===cycleAnswer(task,n)&&w.walk.every((position,i)=>position===cyclePosition(task,i+1,n));if(task.kind==='power'){let digit=1;const sequence=Array.from({length:task.period+1},()=>digit=digit*task.factor%10);ok=ok&&w.period===task.period&&w.generated.length===sequence.length&&w.generated.every((d,i)=>d===sequence[i])&&sequence[0]===sequence.at(-1)&&new Set(sequence.slice(0,-1)).size===task.period}return {ok,incomplete:w.moves===0,reason:'按题目起点实际走到指定计数；第k项从第1项之前起数，过k天从今天0天起走，一基序号余0停末位，零基编号余0回编号0。'};}
function cycleAct(action,data,task){const w=cycleState(task),before=JSON.stringify({...w,log:[]}),value=Number(data.value),base=cycleBase(task,w);let changed=false;
 if(action==='cycleZeroConfirm'&&task.kind==='power'&&task.target===0&&!w.zeroConfirmed){w.zeroConfirmed=true;changed=true}
 if(action==='cycleZeroChoice'&&task.kind==='power'&&task.target===0&&[0,1,4].includes(value)){w.choice=value;changed=true}
 if(action==='cycleMultiply'&&task.kind==='power'&&task.target>0&&!w.ringMade&&w.phase===0&&w.generated.length<task.period+1){w.working=w.digit*task.factor;w.products.push(w.working);w.phase=1;changed=true}
 if(action==='cycleUnits'&&task.kind==='power'&&task.target>0&&!w.ringMade&&w.phase===1){w.working%=10;w.phase=2;changed=true}
 if(action==='cycleCommit'&&task.kind==='power'&&task.target>0&&!w.ringMade&&w.phase===2){w.digit=w.working;w.generated.push(w.digit);w.phase=0;changed=true}
 if(action==='cyclePeriod'&&task.kind==='power'&&task.target>0&&!w.ringMade&&w.generated.length>=task.period+1&&Number.isInteger(value)&&value>=1&&value<w.generated.length){w.period=value;changed=true}
 if(action==='cycleMake'&&task.kind==='power'&&task.target>0&&!w.ringMade&&w.generated.length>=task.period+1&&w.period){w.ringMade=true;w.steps=0;w.cursor=-1;w.walk=[];w.choice=null;changed=true}
 if(['cycleAdvance','cycleRound'].includes(action)&&base.length){const amount=action==='cycleRound'?base.length:1;if(w.steps+amount<=task.target){for(let i=0;i<amount;i++){w.cursor=cycleMod(w.cursor+cycleDirection(task),base.length);w.walk.push(w.cursor);w.steps++}changed=true}}
 if(action==='cycleChoice'&&base.length&&Number.isInteger(value)&&value>=0&&value<=(task.kind==='weekday'||task.indexBase===0?base.length-1:base.length)){w.choice=value;changed=true}
 if(action==='cycleUndo'&&w.log.length){const log=w.log,snapshot=JSON.parse(log.pop()),moves=w.moves+1;Object.assign(w,snapshot,{log,moves});return true}
 if(changed){w.log.push(before);w.moves++;return true}return false;
}
function cycleSpeech(task){const w=cycleState(task),base=cycleBase(task,w);if(task.kind==='power'&&task.target===0)return `零次乘法，原单位${w.zeroConfirmed?'已移到结果盘':'仍在原盘'}；我的个位选择${w.choice??'尚未选择'}。`;if(task.kind==='power'&&!w.ringMade)return `机器内${w.working}，${['等待乘','等待去掉十棒','等待记录末位'][w.phase]}；已生成${w.generated.join('、')||'无'}。`;return `${task.kind==='weekday'?task.direction===-1?'从今天已倒数':'今天起已过':task.indexBase===0?'从编号0已前进':'从第1项之前已数'}${w.steps}${task.kind==='weekday'?'天':task.indexBase===0?'步':'项'}，当前${w.cursor<0?'还没数第一项':base[w.cursor]+(task.indexBase===0?'，轮内编号'+w.cursor:'，周期第'+(w.cursor+1)+'位')}；${base.length?Math.floor(w.steps/base.length):0}整轮，余${base.length?w.steps%base.length:0}。`}
function cyclePage(){const task=CYCLE_TASKS[microSkillId],skill=SKILL_DATA.skills.find(s=>s.id===microSkillId);if(!task||!skill)return '<div class="panel">操作任务不存在。</div>';const board=task.mode==='groupingLab'?groupingBoard(task):task.mode==='patternLab'?patternBoard(task):cycleBoard(task);return `<div class="page-head"><div><p class="kicker">${esc(task.skillId)} · 余数与循环</p><h1>${esc(skill.title)}</h1></div><button class="back" data-action="micro" data-code="${esc(task.skillId)}">← 微技能</button></div><div class="work"><article class="panel"><span class="phase">练 · 操作一题</span><h2 class="task-title">${esc(task.prompt)}</h2><div class="workshop-check-top"><button class="primary" data-action="${feedback?.ok?'next':'check'}">${feedback?.ok?'完成本题，回到微技能 →':'检查操作与理由 ✓'}</button></div>${board}${reasonBlock(task)}${actionRow(task)}</article><aside class="side-stack"><section class="panel"><h3>分清计数起点</h3><p class="muted">数第k项与过k天用不同起点。走整轮会生成并保留真实路径；末位机器需要先乘、只留个位再记录。</p></section></aside></div>`}

