const measureStageTarget=typeof module!=='undefined'?require('./staged').STAGED_TASKS:STAGED_TASKS;
for(const [skillId,cases] of Object.entries(MEASURE_CASES)){
 if(cases.length!==4)throw Error('Four G01 cases required: '+skillId);measureStageTarget[skillId]={};
 for(const [i,kind] of ['transfer','independent','delayed','independent2'].entries()){
  const [params,prompt,explain,changeDimension]=cases[i];measureStageTarget[skillId][kind]={id:`T-${skillId.replace('.', '-')}-${i+1}`,skillId,contentVersion:71,mode:'measureLab',phase:kind==='transfer'?'迁移':kind==='delayed'?'巩固':'测',...params,prompt,explain,changeDimension,...(kind==='transfer'?{hint:'用单位材料实际覆盖、描边或重排，分别检查数量与外边关系。'}:{})};
 }
}
if(typeof module!=='undefined')module.exports={MEASURE_CASES};

'use strict';
function measureState(task){return draft.work??(draft.work={segments:[],edges:[],covered:[],tiles:{},amounts:{length:0,area:0},amountSet:{},traceMode:false,lengthUnit:'',areaUnit:'',moves:0,log:[]})}
function measureCells(task,w){return task.kind==='rearrange'?Object.keys(w.tiles).map(key=>key.split(',').map(Number)):task.cells}
function measureEdges(cells,outerOnly=false){const edges=new Map();for(const [r,c] of cells)for(const key of [`h,${r},${c}`,`h,${r+1},${c}`,`v,${r},${c}`,`v,${r},${c+1}`])edges.set(key,(edges.get(key)||0)+1);return [...edges].filter(([,n])=>!outerOnly||n===1).map(([key])=>key)}
function measureConnected(cells){if(!cells.length)return false;const set=new Set(cells.map(p=>p.join(','))),seen=new Set([cells[0].join(',')]),queue=[cells[0]];while(queue.length){const [r,c]=queue.shift();for(const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]){const key=`${r+dr},${c+dc}`;if(set.has(key)&&!seen.has(key)){seen.add(key);queue.push([r+dr,c+dc])}}}return seen.size===cells.length}
function measureNoHole(task,cells){const set=new Set(cells.map(p=>p.join(','))),seen=new Set(),queue=[];for(let r=0;r<task.rows;r++)for(let c=0;c<task.cols;c++)if((r===0||c===0||r===task.rows-1||c===task.cols-1)&&!set.has(`${r},${c}`)){seen.add(`${r},${c}`);queue.push([r,c])}while(queue.length){const [r,c]=queue.shift();for(const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]){const nr=r+dr,nc=c+dc,key=`${nr},${nc}`;if(nr>=0&&nr<task.rows&&nc>=0&&nc<task.cols&&!set.has(key)&&!seen.has(key)){seen.add(key);queue.push([nr,nc])}}}return seen.size+set.size===task.rows*task.cols}
function measureGrid(task,w){const cells=measureCells(task,w),set=new Set(cells.map(p=>p.join(','))),all=measureEdges(cells),edgeSet=new Set(all),centers=['area','units','rearrange'].includes(task.kind),drawEdges=['perimeter','units'].includes(task.kind)||task.kind==='rearrange'&&w.traceMode,cols=task.cols*2+1,rows=task.rows*2+1;
 const fill=cells.map(([r,c])=>`<rect x="${c*100+25}" y="${r*100+25}" width="100" height="100" fill="${task.kind==='rearrange'||w.covered.includes(`${r},${c}`)?'#f6c779':'#e1ece5'}"/>`).join(''),lines=all.map(key=>{const [axis,r,c]=key.split(','),x=Number(c)*100+25,y=Number(r)*100+25;return `<path d="M${x} ${y}${axis==='h'?'h100':'v100'}" stroke="${w.edges.includes(key)?'#237a98':'#91b1a0'}" stroke-width="${w.edges.includes(key)?7:2}"/>`}).join('');
 const slots=Array.from({length:rows},(_,r)=>Array.from({length:cols},(_,c)=>{if(r%2===0&&c%2===0)return '<span class="measure-vertex"></span>';if(r%2===1&&c%2===1){const key=`${(r-1)/2},${(c-1)/2}`;return centers&&!(task.kind==='rearrange'&&w.traceMode)?`<button class="measure-cell" data-action="measureCell" data-row="${(r-1)/2}" data-col="${(c-1)/2}" aria-label="第${(r+1)/2}行第${(c+1)/2}列${set.has(key)?'目标':'空'}格" aria-pressed="${task.kind==='rearrange'?set.has(key):w.covered.includes(key)}">${task.kind==='rearrange'&&set.has(key)?'■':w.covered.includes(key)?'✓':''}</button>`:'<span></span>'}const axis=r%2===0?'h':'v',er=axis==='h'?r/2:(r-1)/2,ec=axis==='h'?(c-1)/2:c/2,key=`${axis},${er},${ec}`;return drawEdges&&edgeSet.has(key)?`<button class="measure-edge" data-action="measureEdge" data-value="${key}" aria-label="${axis==='h'?'水平':'竖直'}单位边，行${er+1}列${ec+1}" aria-pressed="${w.edges.includes(key)}"></button>`:'<span></span>'}).join('')).join('');
 return `<div class="measure-lattice" style="--measure-cols:${cols};--measure-rows:${rows}" role="group" aria-label="单位方格与可描单位边"><svg viewBox="0 0 ${cols*50} ${rows*50}" aria-hidden="true">${fill}${lines}</svg>${slots}</div>`;
}
function measureReference(task){const cells=task.reference,rows=Math.max(...cells.map(p=>p[0]))+1,cols=Math.max(...cells.map(p=>p[1]))+1;return `<section class="measure-reference"><b>参考图：${cells.length}格，周长${measureEdges(cells,true).length*task.unitSize}${task.unit==='m'?'米':'厘米'}</b><svg viewBox="0 0 ${cols*20+4} ${rows*20+4}" width="${cols*20+4}" height="${rows*20+4}" role="img" aria-label="参考图${cells.length}单位格">${cells.map(([r,c])=>`<rect x="${c*20+2}" y="${r*20+2}" width="20" height="20" fill="#d3e9d9" stroke="#649178"/>`).join('')}</svg></section>`}
function measureAmounts(task,w){const keys=task.kind==='length'||task.kind==='perimeter'?['length']:task.kind==='area'?['area']:['length','area'];return `<div class="measure-amounts">${keys.map(key=>`<section><b>我填${key==='length'?(task.kind==='length'?'长度':'周长'):'面积'}：${w.amounts[key]}</b><div class="work-buttons">${[-10,-1,0,1,5,10].map(d=>`<button data-action="measureAmount" data-key="${key}" data-delta="${d}">${d===0?'填0':d>0?'＋'+d:String(d)}</button>`).join('')}</div></section>`).join('')}</div>`}
function measureBoard(task){const w=measureState(task),undo=`<button data-action="measureUndo" ${w.log.length?'':'disabled'}>↩ 撤回</button>`;
 if(task.kind==='length'){const width=task.max*60+20;return `<div class="board measure-board"><h3>${esc(task.context)} · 每段${task.unitSize}厘米</h3><svg class="measure-ruler" viewBox="0 0 ${width} 95" role="img" aria-label="目标从${task.start*task.unitSize}到${task.end*task.unitSize}厘米"><path d="M${10+task.start*60} 20H${10+task.end*60}" stroke="#d57354" stroke-width="8"/><path d="M10 60H${width-10}" stroke="#688e79" stroke-width="3"/>${Array.from({length:task.max+1},(_,i)=>`<path d="M${10+i*60} 50V70" stroke="#52745f" stroke-width="2"/><text x="${10+i*60}" y="88" text-anchor="middle" font-size="14">${i*task.unitSize}</text>`).join('')}</svg><div class="measure-segments" style="--measure-parts:${task.max}">${Array.from({length:task.max},(_,i)=>`<button data-action="measureSegment" data-index="${i}" aria-pressed="${w.segments.includes(i)}" aria-label="把${task.unitSize}厘米段放在${i*task.unitSize}到${(i+1)*task.unitSize}厘米槽">${w.segments.includes(i)?'━':'空槽'}</button>`).join('')}</div><p>已放${w.segments.length}段，${assessmentFormal(task)?'请自己填写长度':'总单位段量'+w.segments.length*task.unitSize+'厘米'}；仍要核对位置连续覆盖红线。</p><div class="work-buttons">${undo}</div>${measureAmounts(task,w)}</div>`}
 const stock=task.kind==='rearrange'?`<p>待摆${task.total-Object.keys(w.tiles).length}格；当前用了${Object.keys(w.tiles).length}/${task.total}格。${w.traceMode?'现在描新图外边':'点空格放入一块，点已有格收回一块'}。</p><div class="measure-stock" role="img" aria-label="材料盘余${task.total-Object.keys(w.tiles).length}格">${Array.from({length:task.total-Object.keys(w.tiles).length},()=>'<i aria-hidden="true"></i>').join('')}</div><div class="work-buttons"><button data-action="measureTrace" ${Object.keys(w.tiles).length!==task.total?'disabled':''}>摆好，实际描新外边</button><button data-action="measureRearrange" ${!w.traceMode?'disabled':''}>收起描边，继续重排</button></div>`:'';
 const units=task.kind==='units'?`<div class="measure-unit-choices">${[['lengthUnit','外边长度'],['areaUnit','内部面积']].map(([key,name])=>`<section><b>${name}用什么单位？</b><div class="work-buttons">${[['cm','厘米'],['cm2','平方厘米'],['m','米'],['m2','平方米']].map(([value,label])=>`<button data-action="measureUnit" data-key="${key}" data-value="${value}" aria-pressed="${w[key]===value}">${label}</button>`).join('')}</div></section>`).join('')}</div>`:'';
 return `<div class="board measure-board"><h3>${esc(task.context)} · 每格边长${task.unitSize}${task.unit==='m'?'米':'厘米'}</h3>${task.kind==='rearrange'?measureReference(task):''}<div class="work-buttons">${undo}</div>${stock}${measureGrid(task,w)}<p>已描${w.edges.length}单位边，${assessmentFormal(task)?'请自己填写量':'边段量'+w.edges.length*task.unitSize+(task.unit==='m'?'米':'厘米')}；${task.kind==='rearrange'?'当前使用':'已铺'}${task.kind==='rearrange'?Object.keys(w.tiles).length:w.covered.length}单位格。</p>${units}${measureAmounts(task,w)}</div>`;
}
function measureGrade(task){const w=measureState(task),same=(a,b)=>a.length===b.length&&b.every(v=>a.includes(v));let ok=false;if(task.kind==='length')ok=same(w.segments,Array.from({length:task.end-task.start},(_,i)=>task.start+i));else{const cells=measureCells(task,w),outer=measureEdges(cells,true),covered=cells.map(p=>p.join(','));if(task.kind==='perimeter')ok=same(w.edges,outer);if(task.kind==='area')ok=same(w.covered,covered);if(task.kind==='units')ok=same(w.edges,outer)&&same(w.covered,covered)&&w.lengthUnit===task.unit&&w.areaUnit===task.unit+'2';if(task.kind==='rearrange'){const refPerimeter=measureEdges(task.reference,true).length,newPerimeter=outer.length;ok=Object.keys(w.tiles).length===task.total&&new Set(Object.values(w.tiles)).size===task.total&&Object.values(w.tiles).every(id=>Number.isInteger(id)&&id>=0&&id<task.total)&&measureConnected(cells)&&measureNoHole(task,cells)&&w.traceMode&&same(w.edges,outer)&&(task.goal==='samePerimeterDifferentArea'?newPerimeter===refPerimeter&&task.total!==task.reference.length:newPerimeter!==refPerimeter&&task.total===task.reference.length)}}const cells=task.kind==='length'?[]:measureCells(task,w),quantities={length:task.kind==='length'?(task.end-task.start)*task.unitSize:measureEdges(cells,true).length*task.unitSize,area:cells.length*task.unitSize**2},keys=task.kind==='length'||task.kind==='perimeter'?['length']:task.kind==='area'?['area']:['length','area'];ok=ok&&keys.every(key=>w.amountSet[key]&&w.amounts[key]===quantities[key]);return {ok,incomplete:w.moves===0,reason:'连续单位段覆盖目标线；只描目标外边，铺满目标内部。重排要用满原材料、保持连通无洞，并重新核对面积与周长关系。'};}
function measureAct(action,data,task){const w=measureState(task),before=JSON.stringify({...w,log:[]}),index=Number(data.index),r=Number(data.row),c=Number(data.col);let changed=false;const toggle=(list,value)=>{const at=list.indexOf(value);at<0?list.push(value):list.splice(at,1);changed=true};
 if(action==='measureAmount'&&['length','area'].includes(data.key)&&[-10,-1,0,1,5,10].includes(Number(data.delta))){const n=w.amounts[data.key]+Number(data.delta);if(n>=0&&n<=1000){w.amounts[data.key]=n;w.amountSet[data.key]=true;changed=true}}
 if(action==='measureSegment'&&task.kind==='length'&&Number.isInteger(index)&&index>=0&&index<task.max)toggle(w.segments,index);
 if(action==='measureEdge'&&['perimeter','units','rearrange'].includes(task.kind)&&(task.kind!=='rearrange'||w.traceMode)&&measureEdges(measureCells(task,w)).includes(data.value))toggle(w.edges,data.value);
 if(action==='measureCell'&&['area','units','rearrange'].includes(task.kind)&&Number.isInteger(r)&&Number.isInteger(c)&&r>=0&&r<task.rows&&c>=0&&c<task.cols){const key=`${r},${c}`;if(task.kind==='rearrange'){if(w.traceMode)return false;if(w.tiles[key]!==undefined){delete w.tiles[key];changed=true}else if(Object.keys(w.tiles).length<task.total){const used=new Set(Object.values(w.tiles));w.tiles[key]=Array.from({length:task.total},(_,i)=>i).find(id=>!used.has(id));changed=true}}else toggle(w.covered,key)}
 if(action==='measureTrace'&&task.kind==='rearrange'&&Object.keys(w.tiles).length===task.total){w.traceMode=true;changed=true}
 if(action==='measureRearrange'&&task.kind==='rearrange'&&w.traceMode){w.traceMode=false;w.edges=[];changed=true}
 if(action==='measureUnit'&&task.kind==='units'&&['lengthUnit','areaUnit'].includes(data.key)&&['cm','cm2','m','m2'].includes(data.value)){w[data.key]=data.value;changed=true}
 if(action==='measureUndo'&&w.log.length){const log=w.log,snapshot=JSON.parse(log.pop()),moves=w.moves+1;Object.assign(w,snapshot,{log,moves});return true}
 if(changed){w.log.push(before);w.moves++;return true}return false;
}
function measureSpeech(task){const w=measureState(task);if(task.kind==='length')return `已放单位段${w.segments.map(i=>i*task.unitSize+'到'+(i+1)*task.unitSize+'厘米').join('、')||'无'}，${assessmentFormal(task)?'填写长度'+w.amounts.length:'共'+w.segments.length*task.unitSize+'厘米单位段量'}。`;return `已描单位边${w.edges.length}条；已铺${task.kind==='rearrange'?Object.keys(w.tiles).length:w.covered.length}格。${task.kind==='rearrange'?'待摆材料'+(task.total-Object.keys(w.tiles).length)+'格；'+(w.traceMode?'正在描新外边':'正在重排')+'。':''}${task.kind==='units'?'选长度单位'+(w.lengthUnit||'无')+'，面积单位'+(w.areaUnit||'无')+'。':''}`}
