'use strict';
function similarState(task){return draft.work??(draft.work={scaleX:1,scaleY:1,selected:{source:-1,target:-1},links:[],marks:{sourceEdge:-1,targetEdge:-1,sourceAngle:-1,targetAngle:-1},choice:'',trace:{source:[],target:[]},covered:{source:[],target:[]},answer:0,moves:0,log:[]})}
function similarBase(task){return task.points||[[0,0],[task.width,0],[task.width,task.height],[0,task.height]]}
function similarTransform(points,kx,ky,rotation){const a=rotation*Math.PI/180;return points.map(([x,y])=>[kx*x*Math.cos(a)-ky*y*Math.sin(a),kx*x*Math.sin(a)+ky*y*Math.cos(a)])}
function similarWorld(task,side,w){return similarTransform(similarBase(task),side==='source'?1:task.kind==='correspond'?task.factor:w.scaleX,side==='source'?1:task.kind==='correspond'?task.factor:w.scaleY,side==='target'?(task.rotation||0):0)}
function similarDimensions(task,side,w){return {width:task.width*(side==='target'?w.scaleX:1),height:task.height*(side==='target'?w.scaleY:1)}}
function similarBoundary(width,height){if(!Number.isInteger(width)||!Number.isInteger(height)||width<=0||height<=0)return [];const units=[];for(let x=0;x<width;x++)units.push([[x,0],[x+1,0]]);for(let y=0;y<height;y++)units.push([[width,y],[width,y+1]]);for(let x=width;x>0;x--)units.push([[x,height],[x-1,height]]);for(let y=height;y>0;y--)units.push([[0,y],[0,y-1]]);return units}
function similarCells(task,side,w){const d=similarDimensions(task,side,w);if(!Number.isInteger(d.width)||!Number.isInteger(d.height))return [];const remove=new Set(side==='target'&&w.scaleX===task.goalX&&w.scaleY===task.goalY?(task.remove||[]).map(p=>p.join(',')):[]);return Array.from({length:d.height},(_,r)=>Array.from({length:d.width},(_,c)=>`${r},${c}`)).flat().filter(key=>!remove.has(key))}
function similarLabels(task,side){return side==='target'?(task.targetLabels||similarBase(task).map((_,i)=>String.fromCharCode(65+i)+'′')):similarBase(task).map((_,i)=>String.fromCharCode(65+i))}
function similarFigure(task,side,w){const world=similarWorld(task,side,w),cx=(Math.min(...world.map(p=>p[0]))+Math.max(...world.map(p=>p[0])))/2,cy=(Math.min(...world.map(p=>p[1]))+Math.max(...world.map(p=>p[1])))/2,screen=world.map(([x,y])=>[180+(x-cx)*22,180+(y-cy)*22]),labels=similarLabels(task,side),mark=w.marks[side+'Edge'],corner=w.marks[side+'Angle'],unit=v=>{const d=Math.hypot(...v);return v.map(x=>x/d)},lines=screen.map((p,i)=>{const q=screen[(i+1)%screen.length];return `<path d="M${p.join(' ')}L${q.join(' ')}" stroke="${mark===i?'#d0803c':'#658d77'}" stroke-width="${mark===i?7:2}"/>`}).join('');let traces='';if(task.kind==='perimeter'){const d=similarDimensions(task,side,w),segments=similarBoundary(d.width,d.height),rotation=side==='target'?(task.rotation||0):0;traces=w.trace[side].map(e=>{const points=similarTransform(segments[e.id]||[[0,0],[0,0]],1,1,rotation).map(([x,y])=>[180+(x-cx)*22,180+(y-cy)*22]);return `<path data-unit-edge-id="${side}-${e.id}" d="M${points[0].join(' ')}L${points[1].join(' ')}" stroke="#287d9c" stroke-width="7"/>`}).join('')}
 const cuts=task.kind==='area'&&side==='target'&&task.remove&&w.scaleX===task.goalX&&w.scaleY===task.goalY?task.remove.map(([r,c])=>{const points=similarTransform([[c,r],[c+1,r],[c+1,r+1],[c,r+1]],1,1,task.rotation||0).map(([x,y])=>[180+(x-cx)*22,180+(y-cy)*22]);return `<path d="M${points.map(p=>p.join(' ')).join('L')}Z" fill="white" stroke="#9bb9a6" stroke-dasharray="3 2"/>`}).join(''):'';
 const wedge=corner>=0?(()=>{const p=screen[corner],prev=screen[(corner+screen.length-1)%screen.length],next=screen[(corner+1)%screen.length],u=unit(prev.map((v,k)=>v-p[k])),v=unit(next.map((v,k)=>v-p[k]));return `<path d="M${p.join(' ')}L${p.map((x,k)=>x+u[k]*20).join(' ')}L${p.map((x,k)=>x+v[k]*20).join(' ')}Z" fill="#f0c276"/>`})():'';
 return `<div class="similar-canvas"><svg viewBox="0 0 360 360" role="img" aria-label="${side==='source'?'原图':'当前新图'}，顶点${labels.join('、')}"><path d="M${screen.map(p=>p.join(' ')).join('L')}Z" fill="${side==='source'?'#e3f0e4':'#f9e3b6'}"/>${cuts}${lines}${traces}${wedge}${task.kind==='correspond'?'':screen.map((p,i)=>`<text x="${p[0]}" y="${p[1]+(i>1?18:-12)}" text-anchor="middle" font-size="14">${esc(labels[i])}</text>`).join('')}</svg>${task.kind==='correspond'?screen.map((p,i)=>`<button class="similar-point" style="left:${p[0]/3.6}%;top:${p[1]/3.6}%" data-action="similarPoint" data-side="${side}" data-index="${i}" aria-label="${side==='source'?'原图':'新图'}顶点${labels[i]}" aria-pressed="${w.selected[side]===i||w.links.some(pair=>pair[side==='source'?0:1]===i)}">${esc(labels[i])}</button>`).join(''):''}</div>`}
function similarGrid(task,side,w){const d=similarDimensions(task,side,w),cells=new Set(similarCells(task,side,w));if(!Number.isInteger(d.width)||!Number.isInteger(d.height))return '<p class="tiny-note">当前边长不是整数格；本题先调整尺寸，再用1×1单位格铺。</p>';return `<div class="similar-grid" style="--similar-cols:${d.width}" role="group" aria-label="${side==='source'?'原图':'新图'}${d.height}行${d.width}列，同样大小单位格">${Array.from({length:d.height},(_,r)=>Array.from({length:d.width},(_,c)=>{const key=`${r},${c}`,exists=cells.has(key);return `<button class="similar-cell ${w.covered[side].includes(key)?'covered':''} ${exists?'':'cutout'}" data-action="similarCell" data-side="${side}" data-row="${r}" data-col="${c}" aria-label="${side==='source'?'原图':'新图'}第${r+1}行第${c+1}列${exists?'面积格':'预先剪去格'}" aria-pressed="${w.covered[side].includes(key)}" ${exists?'':'disabled'}>${exists?w.covered[side].includes(key)?'■':'空槽':'缺'}</button>`}).join('')).join('')}</div>`}
function similarAnswer(w){return `<div class="work-buttons"><span>我填写${w.answer}倍</span>${[-.25,.25,1].map(delta=>`<button data-action="similarAnswer" data-delta="${delta}" ${w.answer+delta<0?'disabled':''}>${delta>0?'＋':'－'}${Math.abs(delta)}</button>`).join('')}</div>`}
function similarBoard(task){const w=similarState(task),undo=`<button data-action="similarUndo" ${w.log.length?'':'disabled'}>↩ 撤回</button>`;
 if(task.kind==='correspond')return `<div class="board similar-board"><h3>${esc(task.context)}</h3><div class="work-buttons">${undo}</div>${['source','target'].map(side=>{const labels=similarLabels(task,side);return `<section><b>${side==='source'?'原图':'旋转后的新图'}</b>${similarFigure(task,side,w)}<div class="work-buttons">${labels.map((name,i)=>`<button data-action="similarMark" data-side="${side}" data-kind="Edge" data-index="${i}" aria-pressed="${w.marks[side+'Edge']===i}">描${esc(name+labels[(i+1)%labels.length])}边</button><button data-action="similarMark" data-side="${side}" data-kind="Angle" data-index="${i}" aria-pressed="${w.marks[side+'Angle']===i}">标角${esc(name)}</button>`).join('')}</div></section>`}).join('')}<div class="work-buttons"><button data-action="similarLink" ${w.selected.source>=0&&w.selected.target>=0?'':'disabled'}>连接这两个对应点</button></div><div class="similar-links">${w.links.map(([a,b],i)=>`<div><svg viewBox="0 0 160 44" aria-hidden="true"><path d="M22 22H138" stroke="#287c92" stroke-width="3"/><circle cx="22" cy="22" r="7" fill="#84b79a"/><circle cx="138" cy="22" r="7" fill="#e8ad65"/></svg><span>${esc(similarLabels(task,'source')[a])} ↔ ${esc(similarLabels(task,'target')[b])}</span><button data-action="similarUnlink" data-index="${i}">撤去这条连接</button></div>`).join('')}</div></div>`;
 return `<div class="board similar-board"><h3>${esc(task.context)}</h3><p>原尺寸${task.width}×${task.height}；当前新尺寸${task.width*w.scaleX}×${task.height*w.scaleY}。${task.kind==='inverse'?'题目给新对应边'+task.newWidth+'厘米。':''}</p><div class="work-buttons">${undo}${[['both','整体'],['x','宽方向'],['y','高方向']].map(([axis,label])=>`<button data-action="similarScale" data-axis="${axis}" data-delta="-0.5">${label}倍数－0.5</button><button data-action="similarScale" data-axis="${axis}" data-delta="0.5">${label}倍数＋0.5</button>`).join('')}</div><p>当前宽方向${w.scaleX}倍、高方向${w.scaleY}倍。</p>${['source','target'].map(side=>{const d=similarDimensions(task,side,w);return `<section><b>${side==='source'?'原图':'当前新图'}</b>${similarFigure(task,side,w)}${task.kind==='perimeter'?`<button data-action="similarTrace" data-side="${side}" ${!similarBoundary(d.width,d.height).length||w.trace[side].length>=2*(d.width+d.height)?'disabled':''}>沿${side==='source'?'原图':'新图'}外边再描1单位</button><p>实际已描${w.trace[side].length}单位边。</p>`:''}${task.kind==='area'?`${side==='target'&&task.remove?'图中标缺的格已预先剪去，只铺保留区域。':''}${similarGrid(task,side,w)}<p>实际已铺${w.covered[side].length}个单位格。</p>`:''}</section>`}).join('')}${task.kind==='resize'?`<div class="work-buttons">${[['similar','保持相似'],['different','不保持相似']].map(([value,label])=>`<button data-action="similarChoice" data-value="${value}" aria-pressed="${w.choice===value}">${label}</button>`).join('')}</div>`:similarAnswer(w)}</div>`;
}
function similarGrade(task){const w=similarState(task),same=(a,b)=>a.length===b.length&&b.every(v=>a.includes(v)),factor=task.kind==='inverse'?task.newWidth/task.width:task.goalX,axes=w.scaleX===(task.kind==='inverse'?factor:task.goalX)&&w.scaleY===(task.kind==='inverse'?factor:task.goalY);let ok=false;if(task.kind==='correspond')ok=same(w.links.map(pair=>pair.join(',')),similarBase(task).map((_,i)=>`${i},${i}`))&&w.marks.sourceEdge===task.edgeIndex&&w.marks.targetEdge===task.edgeIndex&&w.marks.sourceAngle===task.angleIndex&&w.marks.targetAngle===task.angleIndex&&w.selected.source===-1&&w.selected.target===-1;if(task.kind==='resize')ok=axes&&w.choice===(task.goalX===task.goalY?'similar':'different');if(task.kind==='inverse')ok=axes&&w.answer===factor;if(task.kind==='perimeter')ok=axes&&['source','target'].every(side=>{const d=similarDimensions(task,side,w),segments=similarBoundary(d.width,d.height);return segments.length>0&&w.trace[side].length===segments.length&&w.trace[side].every((e,i)=>e.id===i&&JSON.stringify([e.from,e.to])===JSON.stringify(segments[i]))})&&w.answer===factor;if(task.kind==='area')ok=axes&&['source','target'].every(side=>same(w.covered[side],similarCells(task,side,w)))&&w.answer===similarCells(task,'target',w).length/(task.width*task.height);return {ok,incomplete:w.moves===0,reason:'核对对应点边角，两方向实际缩放；只描外边量周长，铺保留区域量面积。周长按一次倍数，面积按两个方向共同变化。'};}
function similarAct(action,data,task){const w=similarState(task),before=JSON.stringify({...w,log:[]}),index=Number(data.index),delta=Number(data.delta),side=data.side;let changed=false;
 if(action==='similarPoint'&&task.kind==='correspond'&&['source','target'].includes(side)&&Number.isInteger(index)&&index>=0&&index<similarBase(task).length){w.selected[side]=w.selected[side]===index?-1:index;changed=true}
 if(action==='similarLink'&&task.kind==='correspond'&&w.selected.source>=0&&w.selected.target>=0){const pair=[w.selected.source,w.selected.target];if(!w.links.some(p=>p[0]===pair[0]||p[1]===pair[1])){w.links.push(pair);w.selected={source:-1,target:-1};changed=true}}
 if(action==='similarUnlink'&&task.kind==='correspond'&&Number.isInteger(index)&&index>=0&&index<w.links.length){w.links.splice(index,1);changed=true}
 if(action==='similarMark'&&task.kind==='correspond'&&['source','target'].includes(side)&&['Edge','Angle'].includes(data.kind)&&Number.isInteger(index)&&index>=0&&index<similarBase(task).length){w.marks[side+data.kind]=index;changed=true}
 if(action==='similarScale'&&task.kind!=='correspond'&&['both','x','y'].includes(data.axis)&&[-.5,.5].includes(delta)){const keys=data.axis==='both'?['scaleX','scaleY']:[data.axis==='x'?'scaleX':'scaleY'];if(keys.every(key=>w[key]+delta>=.5&&w[key]+delta<=3)){for(const key of keys)w[key]+=delta;w.trace.target=[];w.covered.target=[];w.choice='';changed=true}}
 if(action==='similarTrace'&&task.kind==='perimeter'&&['source','target'].includes(side)){const d=similarDimensions(task,side,w),segments=similarBoundary(d.width,d.height),id=w.trace[side].length;if(id<segments.length){w.trace[side].push({id,from:segments[id][0],to:segments[id][1]});changed=true}}
 if(action==='similarCell'&&task.kind==='area'&&['source','target'].includes(side)){const r=Number(data.row),c=Number(data.col),key=`${r},${c}`;if(Number.isInteger(r)&&Number.isInteger(c)&&similarCells(task,side,w).includes(key)){const at=w.covered[side].indexOf(key);at<0?w.covered[side].push(key):w.covered[side].splice(at,1);changed=true}}
 if(action==='similarChoice'&&task.kind==='resize'&&['similar','different'].includes(data.value)){w.choice=data.value;changed=true}
 if(action==='similarAnswer'&&task.kind!=='correspond'&&task.kind!=='resize'&&[-.25,.25,1].includes(delta)&&w.answer+delta>=0&&w.answer+delta<=16){w.answer+=delta;changed=true}
 if(action==='similarUndo'&&w.log.length){const log=w.log,snapshot=JSON.parse(log.pop()),moves=w.moves+1;Object.assign(w,snapshot,{log,moves});return true}
 if(changed){w.log.push(before);w.moves++;return true}return false;
}
function similarSpeech(task){const w=similarState(task);if(task.kind==='correspond')return `已连接${w.links.map(([a,b])=>similarLabels(task,'source')[a]+'到'+similarLabels(task,'target')[b]).join('、')||'无'}；原图边号${w.marks.sourceEdge+1}和角号${w.marks.sourceAngle+1}，新图边号${w.marks.targetEdge+1}和角号${w.marks.targetAngle+1}。`;return `当前宽方向${w.scaleX}倍，高方向${w.scaleY}倍，新尺寸${task.width*w.scaleX}乘${task.height*w.scaleY}。${task.kind==='perimeter'?'原图描'+w.trace.source.length+'、新图描'+w.trace.target.length+'单位边；':''}${task.kind==='area'?'原图铺'+w.covered.source.length+'、新图铺'+w.covered.target.length+'格；':''}${task.kind==='resize'?'判断'+(w.choice==='similar'?'保持相似':w.choice==='different'?'不保持相似':'未选'):'填写'+w.answer+'倍'}。`}
function similarPage(){const task=SIMILAR_TASKS[microSkillId],skill=SKILL_DATA.skills.find(s=>s.id===microSkillId);if(!task||!skill)return '<div class="panel">操作任务不存在。</div>';return `<div class="page-head"><div><p class="kicker">${esc(task.skillId)} · 对应、缩放与测量</p><h1>${esc(skill.name||skill.title)}</h1></div><button class="back" data-action="micro" data-code="${esc(task.skillId)}">← 微技能</button></div><div class="work"><article class="panel"><span class="phase">练 · 操作一题</span><h2 class="task-title">${esc(task.prompt)}</h2><div class="workshop-check-top"><button class="primary" data-action="${feedback?.ok?'next':'check'}">${feedback?.ok?'完成本题，回到微技能 →':'检查操作与理由 ✓'}</button></div>${similarBoard(task)}${reasonBlock(task)}${actionRow(task)}</article><aside class="side-stack"><section class="panel"><h3>用实际边与方格检验</h3><p class="muted">旋转后保持对应；同比缩放保持边长比。描实际外边与铺实际保留格分别验证周长和面积。</p></section></aside></div>`}
if(typeof module!=='undefined')module.exports={similarTransform,similarBoundary,similarCells,similarWorld,similarDimensions};

